#!/bin/bash
# ---------------------------------------------------------------------------
# Dedicated Edge Node — infrastructure-only bootstrap.
# Generated by Terraform — do not edit manually.
#
# NOTE: This script ONLY prepares base infrastructure. It does NOT install
# containerd, CNI, or EdgeCore — those are installed in later migration gates
# via SSM, keeping this node aligned with the phased E1-E13 plan and avoiding
# any risk of a conflicting/duplicate runtime on the edge node.
# ---------------------------------------------------------------------------

exec > >(tee /var/log/edge-node-init.log) 2>&1
echo "=== Edge node base init started at $(date -u) ==="

echo "[1/3] Updating system packages..."
dnf update -y
dnf install -y aws-cli jq net-tools tcpdump git

echo "[2/3] Creating 1GB swap (safety net for inference workloads)..."
if [ ! -f /swapfile ]; then
  fallocate -l 1G /swapfile
  chmod 600 /swapfile
  mkswap /swapfile
  swapon /swapfile
  echo '/swapfile none swap sw 0 0' >> /etc/fstab
fi

echo "[3/3] Base infrastructure ready."
echo "=== Edge node base init complete at $(date -u) ==="
